SELECT COUNT(*) FROM core_record;
SELECT COUNT(*) FROM (
    SELECT c.coreregistry
    FROM core_record c
    JOIN employment_and_income e ON c.coreregistry = e.emplcoreref
    JOIN expenses_and_assets x ON e.emplcoreref = x.expemplref
    JOIN bank_and_transactions bat ON x.expemplref = bat.bankexpref
    JOIN credit_accounts_and_history cah ON bat.bankexpref = cah.histcompref
    JOIN credit_and_compliance cc ON cah.histcompref = cc.compbankref
) sub;

-- Check if bankrelscore exists in credit_and_compliance or other tables
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%score%' AND table_name IN ('credit_and_compliance', 'credit_accounts_and_history', 'core_record');
